// Build the `run` object `n8n-ingest` records as an `n8n_requests` row.
//
// Shape is fixed by the function's `RunPayload`. `kind` is echoed for
// readability only — the server writes its own constant, so a caller cannot
// forge a marker for another queue.
//
// `fetched: 0` is the honest number and the entire point: we looked, and we
// are not claiming to have ingested anything. Ingesting is the trigger
// workflow's job and it reports its own counts.
//
// Reaching this node means the Gmail call SUCCEEDED — the probe is set to
// stop the workflow on error. That is deliberate: a heartbeat that still
// fired after Gmail started refusing us would keep `finished_at` moving and
// report a healthy sync over a dead credential, which is precisely the
// failure this workflow exists to make visible. A failed run writes no
// marker, `finished_at` goes stale, and the panel says so.
//
// The probe is a plain HTTP call to the Gmail API rather than the Gmail
// node: the node rejected this credential with 'uses invalid credential'
// while the very same credential worked in the Gmail *trigger*. The REST
// call proves the same thing — the token is live and Gmail answers — with
// one less abstraction between us and that fact.

const res = $input.first()?.json ?? {};
const probed = Array.isArray(res.messages) ? res.messages.length : 0;

return [{
  json: {
    messages: [],
    run: {
      kind: 'mail_sync',
      source: 'n8n:mail-heartbeat',
      finished_at: new Date().toISOString(),
      fetched: 0,
      triaged: 0,
      untriaged: 0,
      probed_messages: probed,
    },
  },
}];
